import { create } from 'zustand'
import { persist, createJSONStorage } from 'zustand/middleware'
import { 
  UserProgress, 
  Badge, 
  DailyStats, 
  WeeklyStats,
  Achievement 
} from '../types/quran'

interface ProgressState extends UserProgress {
  // Additional UI state
  isLoading: boolean
  error: string | null
  
  // Computed properties
  todaysStats: DailyStats | null
  weeklyStats: WeeklyStats | null
  monthlyStats: WeeklyStats | null
  availableBadges: Badge[]
  achievements: Achievement[]
  
  // Actions
  initialize: () => Promise<void>
  updateProgress: (ayahNumbers: number[]) => void
  incrementStreak: () => void
  resetStreak: () => void
  updateStreak: () => void
  addXP: (amount: number) => void
  addReadingTime: (minutes: number) => void
  completeLesson: (lessonId: string, xpReward: number) => void
  unlockBadge: (badgeId: string) => void
  updateDailyGoal: (goal: number) => void
  recordStudySession: (ayahsStudied: number, timeSpent: number) => void
  resetProgress: () => void
  
  // Stats and analytics
  getTodaysStats: () => DailyStats
  getWeeklyStats: () => WeeklyStats
  getStreakInfo: () => { current: number, longest: number, freezesAvailable: number, isAtRisk: boolean }
  getLevelInfo: () => { currentLevel: number, xpForNext: number, progress: number }
  getLevelProgress: () => { currentXP: number, xpNeeded: number, percentage: number, xpRemaining: number }
  
  // Badge and achievement system
  checkForNewBadges: () => Badge[]
  checkForNewAchievements: () => Achievement[]
  
  // Utility
  reset: () => void
  setError: (error: string | null) => void
}

// Badge definitions
const DEFAULT_BADGES: Badge[] = [
  {
    id: 'first_day',
    name: 'First Steps',
    description: 'Complete your first lesson',
    icon: '🌟',
    category: 'milestone',
    requirement: 1,
    isUnlocked: false
  },
  {
    id: 'week_warrior',
    name: 'Week Warrior',
    description: 'Maintain a 7-day streak',
    icon: '🔥',
    category: 'streak',
    requirement: 7,
    isUnlocked: false
  },
  {
    id: 'month_master',
    name: 'Month Master',
    description: 'Maintain a 30-day streak',
    icon: '👑',
    category: 'streak',
    requirement: 30,
    isUnlocked: false
  },
  {
    id: 'first_surah',
    name: 'First Surah Complete',
    description: 'Complete your first full surah',
    icon: '📖',
    category: 'completion',
    requirement: 1,
    isUnlocked: false
  },
  {
    id: 'hundred_ayahs',
    name: 'Century Scholar',
    description: 'Memorize 100 ayahs',
    icon: '💯',
    category: 'milestone',
    requirement: 100,
    isUnlocked: false
  },
  {
    id: 'juz_amma',
    name: 'Juz Amma Master',
    description: 'Complete Juz Amma (30th part)',
    icon: '🕌',
    category: 'special',
    requirement: 1,
    isUnlocked: false
  }
]

const XP_PER_LEVEL = 1000
const STREAK_FREEZE_EARN_DAYS = 7

export const useProgressStore = create<ProgressState>()(
  persist(
    (set, get) => ({
      // Initial Progress State
      userId: '',
      memorizedAyahs: [],
      currentSurah: 1,
      currentAyah: 1,
      streak: 0,
      lastStudyDate: '',
      totalXP: 0,
      level: 1,
      dailyGoal: 5, // 5 ayahs per day default
      completedLessons: [],
      badges: [],
      preferences: {
        preferredReciter: '7', // Abdul Basit
        playbackSpeed: 1.0,
        showTransliteration: true,
        showTranslation: true,
        translationLanguage: 'en',
        notificationTime: '19:00', // After Maghrib
        defaultReadingMode: 'learning',
        darkMode: false,
        animationsEnabled: true
      },
      
      // UI State
      isLoading: false,
      error: null,
      todaysStats: null,
      weeklyStats: null,
      monthlyStats: null,
      availableBadges: DEFAULT_BADGES,
      achievements: [],

      // Initialize progress store
      initialize: async () => {
        set({ isLoading: true })
        
        try {
          const state = get()
          
          // Generate today's stats
          const todaysStats = state.getTodaysStats()
          
          // Check for new badges and achievements
          const newBadges = state.checkForNewBadges()
          state.checkForNewAchievements()
          
          set({ 
            todaysStats,
            isLoading: false
          })
          
          // Unlock any earned badges
          newBadges.forEach(badge => {
            if (!state.badges.find(b => b.id === badge.id)) {
              state.unlockBadge(badge.id)
            }
          })
          
        } catch (error) {
          console.error('Failed to initialize progress store:', error)
          set({ 
            error: 'Failed to load progress data',
            isLoading: false
          })
        }
      },

      // Update memorized ayahs
      updateProgress: (ayahNumbers: number[]) => {
        set(state => {
          const newMemorizedAyahs = [
            ...state.memorizedAyahs,
            ...ayahNumbers.filter(num => !state.memorizedAyahs.includes(num))
          ]
          
          return {
            memorizedAyahs: newMemorizedAyahs,
            lastStudyDate: new Date().toISOString()
          }
        })
      },

      // Streak management
      incrementStreak: () => {
        set(state => ({
          streak: state.streak + 1,
          lastStudyDate: new Date().toISOString()
        }))
      },

      resetStreak: () => {
        set({ streak: 0 })
      },

      updateStreak: () => {
        const state = get()
        const today = new Date().toISOString().split('T')[0]
        const lastStudyDay = state.lastStudyDate ? state.lastStudyDate.split('T')[0] : ''
        const yesterday = new Date()
        yesterday.setDate(yesterday.getDate() - 1)
        const yesterdayStr = yesterday.toISOString().split('T')[0]
        
        if (lastStudyDay === today) {
          // Already studied today, maintain streak
          return
        } else if (lastStudyDay === yesterdayStr) {
          // Studied yesterday, increment streak
          state.incrementStreak()
        } else {
          // Streak broken, reset
          state.resetStreak()
        }
      },

      // XP and leveling
      addXP: (amount: number) => {
        set(state => {
          const newTotalXP = state.totalXP + amount
          const newLevel = Math.floor(newTotalXP / XP_PER_LEVEL) + 1
          
          return {
            totalXP: newTotalXP,
            level: newLevel
          }
        })
      },

      addReadingTime: (minutes: number) => {
        const today = new Date().toISOString().split('T')[0]
        
        set(state => {
          // Update today's stats with reading time
          const todaysStats: DailyStats = {
            date: today,
            ayahsStudied: state.todaysStats?.ayahsStudied || 0,
            lessonsCompleted: state.todaysStats?.lessonsCompleted || 0,
            timeSpent: (state.todaysStats?.timeSpent || 0) + minutes,
            xpEarned: state.todaysStats?.xpEarned || 0,
            streakActive: state.streak > 0 && state.lastStudyDate.startsWith(today)
          }
          
          return {
            todaysStats,
            lastStudyDate: new Date().toISOString()
          }
        })
      },

      // Lesson completion
      completeLesson: (lessonId: string, xpReward: number) => {
        set(state => {
          if (state.completedLessons.includes(lessonId)) {
            return state // Already completed
          }
          
          const newCompletedLessons = [...state.completedLessons, lessonId]
          const newTotalXP = state.totalXP + xpReward
          const newLevel = Math.floor(newTotalXP / XP_PER_LEVEL) + 1
          
          return {
            completedLessons: newCompletedLessons,
            totalXP: newTotalXP,
            level: newLevel,
            lastStudyDate: new Date().toISOString()
          }
        })
      },

      // Badge system
      unlockBadge: (badgeId: string) => {
        set(state => {
          const badge = DEFAULT_BADGES.find(b => b.id === badgeId)
          if (!badge || state.badges.find(b => b.id === badgeId)) {
            return state // Badge not found or already unlocked
          }
          
          const unlockedBadge: Badge = {
            ...badge,
            isUnlocked: true,
            earnedAt: new Date().toISOString()
          }
          
          return {
            badges: [...state.badges, unlockedBadge]
          }
        })
      },

      // Settings
      updateDailyGoal: (goal: number) => {
        set({ dailyGoal: Math.max(1, Math.min(goal, 50)) }) // 1-50 range
      },

      resetProgress: () => {
        set({
          memorizedAyahs: [],
          currentSurah: 1,
          currentAyah: 1,
          streak: 0,
          lastStudyDate: '',
          totalXP: 0,
          level: 1,
          completedLessons: [],
          badges: [],
          todaysStats: null,
          weeklyStats: null,
          monthlyStats: null,
          error: null
        })
      },

      // Study session recording
      recordStudySession: (ayahsStudied: number, timeSpent: number) => {
        const today = new Date().toISOString().split('T')[0]
        
        set(state => {
          // Update today's stats
          const todaysStats: DailyStats = {
            date: today,
            ayahsStudied: (state.todaysStats?.ayahsStudied || 0) + ayahsStudied,
            lessonsCompleted: state.todaysStats?.lessonsCompleted || 0,
            timeSpent: (state.todaysStats?.timeSpent || 0) + timeSpent,
            xpEarned: state.todaysStats?.xpEarned || 0,
            streakActive: state.streak > 0 && state.lastStudyDate.startsWith(today)
          }
          
          return {
            todaysStats,
            lastStudyDate: new Date().toISOString()
          }
        })
      },

      // Analytics
      getTodaysStats: (): DailyStats => {
        const today = new Date().toISOString().split('T')[0]
        const state = get()
        
        return {
          date: today,
          ayahsStudied: 0, // Would be calculated from actual study data
          lessonsCompleted: 0,
          timeSpent: 0,
          xpEarned: 0,
          streakActive: state.streak > 0 && state.lastStudyDate.startsWith(today)
        }
      },

      getWeeklyStats: (): WeeklyStats => {
        const today = new Date()
        const weekStart = new Date(today.setDate(today.getDate() - today.getDay()))
        const weekEnd = new Date(weekStart)
        weekEnd.setDate(weekEnd.getDate() + 6)
        
        return {
          weekStart: weekStart.toISOString().split('T')[0],
          weekEnd: weekEnd.toISOString().split('T')[0],
          totalAyahsStudied: 0,
          totalLessonsCompleted: 0,
          totalTimeSpent: 0,
          totalXpEarned: 0,
          averageSessionLength: 0,
          daysActive: 0
        }
      },

      getStreakInfo: () => {
        const state = get()
        const today = new Date().toISOString().split('T')[0]
        const lastStudyDay = state.lastStudyDate ? state.lastStudyDate.split('T')[0] : ''
        const isAtRisk = lastStudyDay !== today && state.streak > 0
        
        return {
          current: state.streak,
          longest: state.streak, // Would track historical longest
          freezesAvailable: Math.floor(state.streak / STREAK_FREEZE_EARN_DAYS),
          isAtRisk
        }
      },

      getLevelProgress: () => {
        const state = get()
        const currentLevelXP = (state.level - 1) * XP_PER_LEVEL
        const nextLevelXP = state.level * XP_PER_LEVEL
        const progressXP = state.totalXP - currentLevelXP
        const xpRemaining = nextLevelXP - state.totalXP
        const percentage = (progressXP / XP_PER_LEVEL) * 100
        
        return {
          currentXP: progressXP,
          xpNeeded: XP_PER_LEVEL,
          percentage,
          xpRemaining
        }
      },

      getLevelInfo: () => {
        const state = get()
        const currentLevelXP = (state.level - 1) * XP_PER_LEVEL
        const nextLevelXP = state.level * XP_PER_LEVEL
        const progressXP = state.totalXP - currentLevelXP
        const xpForNext = nextLevelXP - state.totalXP
        const progress = (progressXP / XP_PER_LEVEL) * 100
        
        return {
          currentLevel: state.level,
          xpForNext,
          progress
        }
      },

      // Badge and achievement checking
      checkForNewBadges: (): Badge[] => {
        const state = get()
        const newBadges: Badge[] = []
        
        DEFAULT_BADGES.forEach(badge => {
          const alreadyUnlocked = state.badges.find(b => b.id === badge.id)
          if (alreadyUnlocked) return
          
          let requirementMet = false
          
          switch (badge.id) {
            case 'first_day':
              requirementMet = state.completedLessons.length >= 1
              break
            case 'week_warrior':
              requirementMet = state.streak >= 7
              break
            case 'month_master':
              requirementMet = state.streak >= 30
              break
            case 'hundred_ayahs':
              requirementMet = state.memorizedAyahs.length >= 100
              break
            default:
              break
          }
          
          if (requirementMet) {
            newBadges.push(badge)
          }
        })
        
        return newBadges
      },

      checkForNewAchievements: (): Achievement[] => {
        // Placeholder for achievement system
        return []
      },

      // Utility
      reset: () => {
        set({
          memorizedAyahs: [],
          currentSurah: 1,
          currentAyah: 1,
          streak: 0,
          lastStudyDate: '',
          totalXP: 0,
          level: 1,
          completedLessons: [],
          badges: [],
          todaysStats: null,
          weeklyStats: null,
          monthlyStats: null,
          error: null
        })
      },

      setError: (error: string | null) => set({ error })
    }),
    {
      name: 'progress-store',
      storage: createJSONStorage(() => localStorage),
      // Persist all progress data
      partialize: (state) => ({
        userId: state.userId,
        memorizedAyahs: state.memorizedAyahs,
        currentSurah: state.currentSurah,
        currentAyah: state.currentAyah,
        streak: state.streak,
        lastStudyDate: state.lastStudyDate,
        totalXP: state.totalXP,
        level: state.level,
        dailyGoal: state.dailyGoal,
        completedLessons: state.completedLessons,
        badges: state.badges,
        preferences: state.preferences
      })
    }
  )
)