import { create } from 'zustand'
import { persist, createJSONStorage } from 'zustand/middleware'

export interface User {
  id: string
  email?: string
  displayName: string
  hasCompletedOnboarding: boolean
  createdAt: string
  lastLoginAt: string
  isGuest: boolean
}

interface AuthState {
  user: User | null
  isAuthenticated: boolean
  isLoading: boolean
  error: string | null
  
  // Actions
  initialize: () => Promise<void>
  signInAsGuest: (displayName: string) => Promise<void>
  signInWithEmail: (email: string, password: string) => Promise<void>
  signUp: (email: string, password: string, displayName: string) => Promise<void>
  signOut: () => Promise<void>
  logout: () => Promise<void>
  setUser: (user: User | null) => void
  updateProfile: (updates: Partial<User>) => Promise<void>
  completeOnboarding: () => void
  setError: (error: string | null) => void
  clearError: () => void
}

export const useAuthStore = create<AuthState>()(
  persist(
    (set, get) => ({
      // Initial State
      user: null,
      isAuthenticated: false,
      isLoading: false,
      error: null,

      // Initialize authentication state
      initialize: async () => {
        set({ isLoading: true })
        
        try {
          // Check if user was previously signed in
          const state = get()
          if (state.user) {
            set({ 
              isAuthenticated: true,
              user: {
                ...state.user,
                lastLoginAt: new Date().toISOString()
              }
            })
          }
        } catch (error) {
          console.error('Auth initialization failed:', error)
          set({ error: 'Failed to restore session' })
        } finally {
          set({ isLoading: false })
        }
      },

      // Sign in as guest (no email required)
      signInAsGuest: async (displayName: string) => {
        set({ isLoading: true, error: null })
        
        try {
          const user: User = {
            id: `guest_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            displayName: displayName.trim(),
            hasCompletedOnboarding: false,
            createdAt: new Date().toISOString(),
            lastLoginAt: new Date().toISOString(),
            isGuest: true
          }
          
          set({ 
            user,
            isAuthenticated: true,
            isLoading: false
          })
          
        } catch (error) {
          console.error('Guest sign in failed:', error)
          set({ 
            error: 'Failed to sign in as guest',
            isLoading: false
          })
        }
      },

      // Sign in with email (future implementation)
      signInWithEmail: async (email: string, _password: string) => {
        set({ isLoading: true, error: null })
        
        try {
          // TODO: Implement actual email authentication
          // For now, create a mock user
          const user: User = {
            id: `user_${Date.now()}`,
            email,
            displayName: email.split('@')[0],
            hasCompletedOnboarding: false,
            createdAt: new Date().toISOString(),
            lastLoginAt: new Date().toISOString(),
            isGuest: false
          }
          
          set({ 
            user,
            isAuthenticated: true,
            isLoading: false
          })
          
        } catch (error) {
          console.error('Email sign in failed:', error)
          set({ 
            error: 'Failed to sign in with email',
            isLoading: false
          })
        }
      },

      // Sign up with email (future implementation)
      signUp: async (email: string, _password: string, displayName: string) => {
        set({ isLoading: true, error: null })
        
        try {
          // TODO: Implement actual email signup
          // For now, create a mock user
          const user: User = {
            id: `user_${Date.now()}`,
            email,
            displayName: displayName.trim(),
            hasCompletedOnboarding: false,
            createdAt: new Date().toISOString(),
            lastLoginAt: new Date().toISOString(),
            isGuest: false
          }
          
          set({ 
            user,
            isAuthenticated: true,
            isLoading: false
          })
          
        } catch (error) {
          console.error('Sign up failed:', error)
          set({ 
            error: 'Failed to create account',
            isLoading: false
          })
        }
      },

      // Sign out
      signOut: async () => {
        set({ isLoading: true })
        
        try {
          // Clear user data
          set({ 
            user: null,
            isAuthenticated: false,
            error: null,
            isLoading: false
          })
          
          // Clear other stores if needed
          localStorage.removeItem('progress-store')
          localStorage.removeItem('preferences-store')
          
        } catch (error) {
          console.error('Sign out failed:', error)
          set({ 
            error: 'Failed to sign out',
            isLoading: false
          })
        }
      },

      // Update user profile
      updateProfile: async (updates: Partial<User>) => {
        const { user } = get()
        if (!user) {
          set({ error: 'No user to update' })
          return
        }
        
        set({ isLoading: true, error: null })
        
        try {
          const updatedUser: User = {
            ...user,
            ...updates,
            lastLoginAt: new Date().toISOString()
          }
          
          set({ 
            user: updatedUser,
            isLoading: false
          })
          
        } catch (error) {
          console.error('Profile update failed:', error)
          set({ 
            error: 'Failed to update profile',
            isLoading: false
          })
        }
      },

      // Logout alias for signOut
      logout: async () => {
        return get().signOut()
      },

      // Set user directly
      setUser: (user: User | null) => {
        set({ 
          user,
          isAuthenticated: !!user
        })
      },

      // Mark onboarding as complete
      completeOnboarding: () => {
        const { user } = get()
        if (user) {
          set({ 
            user: {
              ...user,
              hasCompletedOnboarding: true
            }
          })
        }
      },

      // Error handling
      setError: (error: string | null) => set({ error }),
      
      clearError: () => set({ error: null })
    }),
    {
      name: 'auth-store',
      storage: createJSONStorage(() => localStorage),
      // Persist user data and auth state
      partialize: (state) => ({
        user: state.user,
        isAuthenticated: state.isAuthenticated
      })
    }
  )
)